"""Selected original page-only DOM expressions, embedded in Python. No backend JavaScript runtime."""
import json

READIDENTITY = "function readIdentity(){\n const text=document.body?.innerText||document.body?.textContent||'';\n const handle=(text.match(/小红书(?:账号|号)\\s*[:：]?\\s*([A-Za-z0-9_.-]+)/)||[])[1]||'';\n const name=(document.querySelector('.account-name, .user-info .name-box')?.textContent||'').trim();\n const followerLabel=[...document.querySelectorAll('span')].find(e=>e.textContent?.trim()==='粉丝数'&&e.parentElement?.querySelector('.numerical'));\n const followerText=followerLabel?.parentElement?.querySelector('.numerical')?.textContent?.trim()||'';\n const match=followerText.match(/^([\\d,.]+)\\s*(万|亿)?$/);\n const followers=match?Math.round(Number(match[1].replaceAll(',',''))*(match[2]==='万'?10000:match[2]==='亿'?1e8:1)):null;\n // The creator UI does not render the numeric account handle on every route\n // (notably note-manager and publish/publish).  The verified binding in the\n // workspace supplies that handle; here we only assert that this is a live,\n // non-login creator page with the visible account name.  Callers still\n // compare any handle that is present and always compare the account name.\n return {url:location.href,name,handle,followers,loggedIn:location.origin==='https://creator.xiaohongshu.com'&&!location.pathname.includes('login')&&!!name};\n}"
READCREATORIDENTITY = "async function readCreatorIdentity(requireUserId=false){\n const text=document.body?.innerText||document.body?.textContent||'';\n const domHandle=(text.match(/小红书(?:账号|号)\\s*[:：]?\\s*([A-Za-z0-9_.-]+)/)||[])[1]||'';\n const name=(document.querySelector('.account-name, .user-info .name-box')?.textContent||'').trim();\n const followerLabel=[...document.querySelectorAll('span')].find(e=>e.textContent?.trim()==='粉丝数'&&e.parentElement?.querySelector('.numerical'));\n const followerText=followerLabel?.parentElement?.querySelector('.numerical')?.textContent?.trim()||'';\n const match=followerText.match(/^([\\d,.]+)\\s*(万|亿)?$/);\n const followers=match?Math.round(Number(match[1].replaceAll(',',''))*(match[2]==='万'?10000:match[2]==='亿'?1e8:1)):null;\n const base={url:location.href,name,handle:domHandle,followers,loggedIn:location.origin==='https://creator.xiaohongshu.com'&&!location.pathname.includes('login')&&!!name};\n if(!base.loggedIn&&location.pathname.includes('login'))return {...base,status:'unknown'};\n const cached=window.__MATRIX_XHS_CREATOR_IDENTITY;\n if(cached?.value?.loggedIn&&(!requireUserId||cached.value.userId)&&Number.isFinite(cached.at)&&Date.now()-cached.at<5000)return {...cached.value,url:location.href};\n if(base.loggedIn&&domHandle&&!requireUserId){const value={...base,status:'authenticated',source:'creator-dom'};try{window.__MATRIX_XHS_CREATOR_IDENTITY={at:Date.now(),value};}catch{}return value;}\n const unknown={...base,loggedIn:false,status:'unknown'};\n const endpoints=['/api/galaxy/user/info','https://creator.xiaohongshu.com/api/galaxy/user/info'];\n let lastError='创作后台身份接口未返回完整的当前登录账号信息';\n for(const endpoint of endpoints){\n  let response;\n  try{response=await fetch(endpoint,{credentials:'include',headers:{Accept:'application/json'}});}catch{lastError='创作后台身份接口暂时无法访问';continue;}\n  if([401,403,429].includes(response.status))return {...unknown,error:`创作后台身份接口返回 HTTP ${response.status}`};\n  if(!response.ok){lastError=`创作后台身份接口返回 HTTP ${response.status}`;continue;}\n  let payload;\n  try{payload=await response.json();}catch{lastError='创作后台身份接口返回了无法读取的结果';continue;}\n  const unwrap=value=>value?.value??value?._value??value;\n  const root=unwrap(payload),data=unwrap(root?.data??root),self=unwrap(data?.userInfo??data?.user_info??data?.user??data);\n  const handle=String(self?.redId??self?.red_id??data?.redId??data?.red_id??'');\n  const userId=String(self?.userId??self?.user_id??data?.userId??data?.user_id??'');\n  const apiName=String(self?.nickname??self?.nickName??self?.name??data?.nickname??data?.nickName??data?.name??'').trim();\n  const loggedIn=root?.loggedIn??data?.loggedIn;\n  const guest=self?.guest??data?.guest;\n  if(guest===true||loggedIn===false) return {...unknown,status:'guest'};\n  if(handle&&userId&&(loggedIn===undefined||loggedIn===true)){const value={...base,loggedIn:true,status:'authenticated',source:'creator-self-api',handle,userId,name:apiName||name};try{window.__MATRIX_XHS_CREATOR_IDENTITY={at:Date.now(),value};window.__MATRIX_XHS_CREATOR_IDENTITY_ENDPOINT=endpoint;}catch{}return value;}\n  lastError='创作后台身份接口未返回完整的当前登录账号信息';\n }\n return {...unknown,error:lastError};\n}"
READWEBIDENTITY = "async function readWebIdentity(){\n const unknown={url:location.href,status:'unknown',loggedIn:false,userId:'',redId:'',name:''};\n const identityFromPayload=(payload,source)=>{\n  const unwrap=value=>value?.value??value?._value??value;\n  const root=unwrap(payload);\n  const data=unwrap(root?.data??root);\n  const self=unwrap(data?.userInfo??data?.user_info??data?.user??data);\n  const loggedIn=unwrap(root?.loggedIn??data?.loggedIn);\n  const guest=self?.guest??data?.guest;\n  const userId=String(self?.userId??self?.user_id??data?.userId??data?.user_id??'');\n  const redId=String(self?.redId??self?.red_id??data?.redId??data?.red_id??'');\n  const name=String(self?.nickname??self?.nickName??self?.name??data?.nickname??data?.nickName??data?.name??'');\n  if(guest===true||loggedIn===false)return {...unknown,status:'guest',source};\n  if(source==='web-self-state'){\n   if(loggedIn!==true||!userId||!redId)return null;\n   return {url:location.href,status:'authenticated',loggedIn:true,userId,redId,name,source};\n  }\n  if(source==='web-self-api'&&guest!==true&&userId&&redId)return {url:location.href,status:'authenticated',loggedIn:true,userId,redId,name,source};\n  if(guest!==false||!userId||!redId)return null;\n  return {url:location.href,status:'authenticated',loggedIn:true,userId,redId,name,source};\n };\n try{\n  const state=window.__INITIAL_STATE__;\n  const legacy=state?.user;\n  if(legacy){\n   const parsed=identityFromPayload(legacy,'web-self-state');\n   if(parsed)return parsed;\n   const legacyRoot=legacy?.value??legacy?._value??legacy;\n   const legacyLoggedIn=legacyRoot?.loggedIn?.value??legacyRoot?.loggedIn;\n   const legacySelf=legacyRoot?.userInfo?.value??legacyRoot?.userInfo;\n   if(legacyLoggedIn===false||legacySelf?.guest===true)return {...unknown,status:'guest',source:'web-self-state'};\n  }\n  // Newer XHS builds no longer expose the self identity in INITIAL_STATE.\n  // Read the page's own authenticated endpoint once, with browser cookies;\n  // never use a viewed profile or a generic nickname as identity evidence.\n  let lastError='网页版身份接口未返回完整的当前登录账号信息';\n  const preferred=typeof window.__MATRIX_XHS_IDENTITY_ENDPOINT==='string'?window.__MATRIX_XHS_IDENTITY_ENDPOINT:'';\n  const endpoints=[preferred,'/api/sns/web/v1/user/selfinfo','/api/sns/web/v2/user/me','https://edith.xiaohongshu.com/api/sns/web/v1/user/selfinfo','https://edith.xiaohongshu.com/api/sns/web/v2/user/me','https://edith.xiaohongshu.com/api/sns/web/v1/user/me','/api/sns/web/v1/user/me'].filter((endpoint,index,list)=>endpoint&&list.indexOf(endpoint)===index);\n  for(const endpoint of endpoints){\n   let response;\n   try{response=await fetch(endpoint,{credentials:'include',headers:{Accept:'application/json'}});}catch{lastError='网页版身份接口暂时无法访问';continue;}\n   if([401,403,429].includes(response.status))return {...unknown,error:`网页版身份接口返回 HTTP ${response.status}`};\n   if(!response.ok){lastError=`网页版身份接口返回 HTTP ${response.status}`;continue;}\n   const parsed=identityFromPayload(await response.json(),'web-self-api');\n   if(parsed){try{window.__MATRIX_XHS_IDENTITY_ENDPOINT=endpoint;}catch{}return parsed;}\n   lastError='网页版身份接口未返回完整的当前登录账号信息';\n  }\n  return {...unknown,error:lastError};\n }catch{return {...unknown,error:'网页版自身登录状态暂时无法读取'};}\n}"
READEDITOR = 'function readEditor(){\n const root=document.querySelector(\'#web\');\n const title=root?.querySelector(\'input[placeholder*="标题"]\');\n const body=root?.querySelector(\'[contenteditable=true]\');\n const copy=body?.cloneNode(true);copy?.querySelectorAll(\'.content-hide\').forEach(e=>e.remove());\n const topics=[...(body?.querySelectorAll(\'a.tiptap-topic[data-topic]\')??[])].map(e=>{try{return JSON.parse(e.getAttribute(\'data-topic\'));}catch{return {};}});\n const images=[...(root?.querySelectorAll(\'.format-img img.preview\')??[])];\n return {topics,title:title?.value??\'\',text:body?.classList.contains(\'ProseMirror\')?[...copy.children].map(p=>p.textContent??\'\').join(\'\\n\'):(body?.innerText??\'\'),imageCount:images.filter(i=>i.complete&&i.naturalWidth>0).length,pendingImageCount:root?.querySelectorAll(\'.format-img\').length??0,editor:!!title&&!!body,url:location.href};\n}'
FILLEDITOR = 'function fillEditor(task){\n const root=document.querySelector(\'#web\');\n const title=root?.querySelector(\'input[placeholder*="标题"]\');\n const body=root?.querySelector(\'[contenteditable=true]\');\n if(!title||!body)throw Error(\'未找到标题或正文输入框\');\n const text=task.body+(task.tags.length?\'\\n\'+task.tags.map(t=>\'#\'+t).join(\' \'):\'\');\n Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,\'value\').set.call(title,task.title);\n title.dispatchEvent(new Event(\'input\',{bubbles:true}));\n title.dispatchEvent(new Event(\'change\',{bubbles:true}));\n body.focus();\n body.replaceChildren(...text.split(\'\\n\').map(line=>{const p=document.createElement(\'p\');if(line)p.textContent=line;else p.append(document.createElement(\'br\'));return p;}));\n body.dispatchEvent(new InputEvent(\'input\',{bubbles:true,inputType:\'insertText\',data:text}));\n return true;\n}'
READTITLEPREVIEW = "function readTitlePreview(title){\n const visible=e=>e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0;\n return [...document.querySelectorAll('#web .title, #web .ellipsis.small')].some(e=>visible(e)&&e.textContent.trim()===title);\n}"
READPERSISTEDIMAGEDRAFT = "async function readPersistedImageDraft(title,{timeoutMs=4000,attempts=2}={}){\n // The function is serialized into Chrome, so helpers must remain inside it.\n // Retry reads only. Never interpret a stalled store as an empty draft box.\n for(let attempt=1;attempt<=attempts;attempt++){\n let db,transaction,expired=false,stage='草稿库枚举',timer;\n const read=async()=>{\n const databases=await indexedDB.databases();if(expired)return;\n if(!databases.some(d=>d.name==='draft-database-v1'))return {available:false,matches:0};\n stage='草稿库打开';\n const opened=indexedDB.open('draft-database-v1');db=await new Promise((resolve,reject)=>{opened.onsuccess=()=>{if(expired){opened.result.close();resolve(null);}else resolve(opened.result);};opened.onerror=()=>reject(opened.error);opened.onblocked=()=>reject(Error('平台草稿库被占用，请关闭该账号其他创作页面后重试'));});\n if(expired||!db)return;\n try{\n  if(!db.objectStoreNames.contains('image-draft'))return {available:false,matches:0};\n  const uid=localStorage.getItem('snsWebPublishCurrentUser');if(!uid)return {available:false,matches:0};\n  stage='草稿内容读取';transaction=db.transaction('image-draft','readonly');\n  const request=transaction.objectStore('image-draft').getAll();\n  const rows=await new Promise((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});\n  const matches=rows.filter(row=>row.uid===uid&&row.content?.draftStore?.title===title);\n  return {available:true,matches:matches.length,draftIds:matches.map(row=>row.draftId),records:matches.map(row=>({draftId:row.draftId,uid:row.uid,timeStamp:row.timeStamp,title:row.content.draftStore.title,body:row.content.draftStore.desc,images:row.content.draftStore.imgList?.map(image=>({fileId:image.fileId,status:image.status})),tags:row.content.draftStore.hashTag})) };\n }finally{db.close();}\n };\n try{return await Promise.race([read(),new Promise((_,reject)=>{timer=setTimeout(()=>{expired=true;try{transaction?.abort();}catch{}db?.close();reject(Error(stage+'超时，未确认现有草稿，已停止上传'));},timeoutMs);})]);}\n catch(error){if(!expired||attempt===attempts)throw error;}\n finally{clearTimeout(timer);}\n }\n}"
UPLOADEDDRAFTFILEIDS = "function uploadedDraftFileIds(){\n const states=[];for(const e of document.querySelectorAll('*'))if(e.__vue_app__){const provides=e.__vue_app__._context?.provides;if(!provides)continue;for(const key of Reflect.ownKeys(provides)){const draft=provides[key]?.state?.value?.draft;if(draft?.imgList?.length)states.push(draft.imgList);}}\n if(states.length!==1||states[0].some(image=>!image.fileId||image.status!==2))throw Error('图片上传尚未得到平台文件编号');\n return states[0].map(image=>image.fileId);\n}"
INSPECTDRAFTLIST = 'function inspectDraftList(title){\n const visible=e=>e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0;\n const drawer=[...document.querySelectorAll(\'.draft-drawer\')].find(visible);\n const list=drawer?.querySelector(\'.draft-list\');\n const rows=[...(list?.querySelectorAll(\'.draft-item[data-draft-id][data-draft-type="image"]\')??[])].filter(e=>visible(e)&&e.querySelector(\'.draft-title-text\')?.textContent.trim()===title);\n return {matches:rows.length,draftIds:rows.map(e=>e.getAttribute(\'data-draft-id\')),drawer:!!drawer,saved:document.body.innerText.includes(\'保存成功\'),text:drawer?.innerText?.slice(-5000)??\'\'};\n}'
OPENIMAGEDRAFTS = "function openImageDrafts(){\n const visible=e=>e.getBoundingClientRect().width>0&&e.getBoundingClientRect().height>0;\n const drawer=[...document.querySelectorAll('.draft-drawer')].find(visible);\n if(!drawer){\n  const entry=[...document.querySelectorAll('body *')].find(e=>visible(e)&&!e.children.length&&/^草稿箱\\(\\d+\\)$/.test(e.textContent.trim()));\n  entry?.click();return !!entry;\n }\n const tab=[...drawer.querySelectorAll('.tab-item')].find(e=>/^图文笔记\\(\\d+\\)$/.test(e.textContent.trim()));\n if(tab&&!tab.classList.contains('active'))tab.click();\n return !!tab;\n}"
REFRESHPLATFORMDRAFTLIST = 'async function refreshPlatformDraftList(){\n if(document.querySelector(\'#web input[placeholder*="标题"],.tiptap[contenteditable="true"]\'))return {refreshed:false,reason:\'editor-active\'};\n if(!localStorage.getItem(\'snsWebPublishCurrentUser\'))return {refreshed:false,reason:\'identity-missing\'};\n const components=[],seen=new Set();\n const walk=v=>{if(!v||seen.has(v))return;seen.add(v);if(v.component){const c=v.component;if(c.type?.__name===\'DraftBox\'&&c.render?.toString().includes(\'draft-title-box\')&&c.isMounted&&c.m?.length===1)components.push(c);walk(c.subTree);}if(Array.isArray(v.children))v.children.forEach(walk);if(Array.isArray(v.dynamicChildren))v.dynamicChildren.forEach(walk);walk(v.suspense?.activeBranch);walk(v.ssContent);};\n for(const e of document.querySelectorAll(\'*\'))if(e.__vue_app__)walk(e._vnode);\n if(components.length!==1)return {refreshed:false,reason:\'unsupported-platform-version\'};\n await components[0].m[0]();return {refreshed:true};\n}'
READNATIVETOPICS = "function readNativeTopics(){\n return [...document.querySelectorAll('#web [contenteditable=true] a.tiptap-topic[data-topic]')].map(e=>{try{return JSON.parse(e.getAttribute('data-topic'));}catch{return {};}});\n}"
FINDTOPICCANDIDATE = "function findTopicCandidate(name){\n const matches=[...document.querySelectorAll('.item[data-impression]')].filter(e=>{\n  const r=e.getBoundingClientRect();\n  if(!r.width||!r.height||e.closest('[contenteditable=true]'))return false;\n  if(e.querySelector('.name')?.textContent?.trim()!=='#'+name)return false;\n  try{return !!JSON.parse(e.getAttribute('data-impression')).tagTarget?.value?.tagId;}catch{return false;}\n });\n if(matches.length!==1)return null;\n const e=matches[0];e.scrollIntoView({block:'nearest'});const r=e.getBoundingClientRect();\n return {id:JSON.parse(e.getAttribute('data-impression')).tagTarget.value.tagId,x:r.x+r.width/2,y:r.y+r.height/2};\n}"
IMAGETABTARGET = "function imageTabTarget(){\n const root=document.querySelector('#web');\n if(!root)return {reason:'创作页面尚未就绪'};\n if(root.querySelector('[contenteditable=true],video,.format-img')||[...root.querySelectorAll('input,textarea')].some(e=>e.type==='file'?e.files?.length:e.value?.trim()))return {reason:'当前创作页已有未保存内容，已保留原页面'};\n const candidates=[...root.querySelectorAll('.creator-tab')].filter(e=>e.textContent.trim()==='上传图文').filter(e=>{\n  const r=e.getBoundingClientRect(),s=getComputedStyle(e);\n  return r.width>0&&r.height>0&&r.x>=0&&r.y>=0&&Number(s.opacity)>0.5&&s.visibility!=='hidden'&&e.getAttribute('aria-hidden')!=='true'&&e.contains(document.elementFromPoint(r.x+r.width/2,r.y+r.height/2));\n });\n if(candidates.length!==1)return {reason:'未找到唯一可点击的上传图文入口'};\n const r=candidates[0].getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2};\n}"
READWEBNOTE = "function readWebNote(id){\n const raw=window.__INITIAL_STATE__?.note?.noteDetailMap;\n const map=raw?.value??raw;const entry=map?.[id];const n=entry?.note?.value??entry?.note;\n if(!n||n.noteId!==id)return null;\n const streams=n.video?.media?.stream||{};\n const videos=Object.values(streams).flat().filter(s=>s&&typeof s==='object');\n const stream=videos.find(s=>s.videoCodec==='h264'||s.video_codec==='h264')||videos.find(s=>s.masterUrl||s.master_url);\n return {noteId:n.noteId,title:n.title||'',desc:typeof n.desc==='string'?n.desc:null,type:n.type,time:n.time,\n  user:{userId:n.user?.userId||n.user?.user_id||''},\n  imageList:(n.imageList||[]).slice(0,100).map(i=>({urlDefault:i.urlDefault||i.url_default||i.url||i.urlPre||''})),\n  interactInfo:{likedCount:n.interactInfo?.likedCount,collectedCount:n.interactInfo?.collectedCount,commentCount:n.interactInfo?.commentCount,shareCount:n.interactInfo?.shareCount},\n  video:stream?{url:stream.masterUrl||stream.master_url}:undefined};\n}"
READCONTENTPAGE = 'function readContentPage(){\n // Framework state can be enormous, circular, and too deeply nested for CDP\n // serialization.  Structured API responses are collected through Network;\n // this DOM reader deliberately returns no framework state and stays safe on\n // every route.\n const safe={};\n const links=[...document.querySelectorAll(\'a[href]\')].map(a=>({text:a.textContent.trim(),url:a.href}));\n const next=[...document.querySelectorAll(\'button,a,[role="button"]\')].filter(e=>/^(下一页|下一页 >|Next)$/i.test((e.innerText||e.getAttribute(\'aria-label\')||\'\').trim()));\n const cards=[...document.querySelectorAll(\'.note-card\')].map(card=>{\n  const impression=card.getAttribute(\'data-impression\')||\'\';\n  const noteId=(impression.match(/noteId[^\\dA-Za-z_-]*([\\w-]+)/)||[])[1]||\'\';\n  const title=card.querySelector(\'.note-card__title\')?.textContent?.trim()||\'\';\n  const publishedAt=card.querySelector(\'.note-card__time\')?.textContent?.trim()||\'\';\n  const cover=card.querySelector(\'.note-card__media img.content\')?.src||card.querySelector(\'.note-card__media .media-bg\')?.style.backgroundImage?.match(/url\\(["\']?(.*?)["\']?\\)/)?.[1]||null;\n  const mediaType=card.querySelector(\'.note-card__media img.play\')?\'video\':\'image\';\n  const stats=[...card.querySelectorAll(\'.note-card__stats .note-card__stat, .note-card__stat\')].map(e=>Number((e.textContent||\'\').trim())).filter(Number.isFinite);\n  return {id:noteId,title,publishedAt,cover,mediaType,stats};\n }).filter(c=>c.title);\n return {state:safe,url:location.href,text:(document.body?.innerText||\'\').slice(0,12000),links,cards,nextCount:next.length,nextEnabled:next.length===1&&!next[0].disabled&&next[0].getAttribute(\'aria-disabled\')!==\'true\'};\n}'

def expression(source,*args):
    return "("+source+")("+",".join(json.dumps(arg,ensure_ascii=False,separators=(",",":")) for arg in args)+")"
